require_once __DIR__.'/../includes/auth.php';require_login();if(!super_admin_role()){http_response_code(403);exit('Only a Super Admin may run database upgrades.');}$message='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_check((string)($_POST['csrf_token']??'')))$error='Your session expired. Refresh and try again.';else try{db()->exec("CREATE TABLE IF NOT EXISTS management_bank_deposit_records (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,management_property_id BIGINT UNSIGNED NOT NULL,deposit_date DATE NOT NULL,cash_amount DECIMAL(14,2) NOT NULL DEFAULT 0.00,check_amount DECIMAL(14,2) NOT NULL DEFAULT 0.00,refunds_description TEXT NULL,upload_group VARCHAR(64) NOT NULL DEFAULT '',created_by_admin_user_id BIGINT UNSIGNED NULL,updated_by_admin_user_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_management_bank_deposit_date(management_property_id,deposit_date),KEY idx_management_bank_deposit_month(management_property_id,deposit_date),KEY idx_management_bank_deposit_group(management_property_id,upload_group)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");if(!db()->query("SHOW COLUMNS FROM management_bank_deposit_records LIKE 'upload_group'")->fetchColumn())db()->exec("ALTER TABLE management_bank_deposit_records ADD COLUMN upload_group VARCHAR(64) NOT NULL DEFAULT '' AFTER refunds_description");db()->exec("UPDATE management_bank_deposit_records SET upload_group=CONCAT('record-',id) WHERE upload_group=''");db()->exec("CREATE TABLE IF NOT EXISTS management_bank_deposit_files (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,management_property_id BIGINT UNSIGNED NOT NULL,upload_group VARCHAR(64) NOT NULL,file_path VARCHAR(500) NOT NULL,original_name VARCHAR(255) NOT NULL,mime_type VARCHAR(150) NOT NULL,file_size BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_management_bank_deposit_files_group(management_property_id,upload_group)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$message='Bank Deposits are installed.';}catch(Throwable $exception){$error=$exception->getMessage();error_log('Bank Deposits upgrade failed: '.$exception->getMessage());}}
